// Simulates OCR: renders each mock invoice's structured fields into a
// plain-text invoice document, the way a real scanned/emailed invoice
// would arrive as raw text before Tesseract + the LLM ever see it. This
// is what lets the demo exercise the REAL /ingest pipeline (OCR-shaped
// text in, LLM-structured JSON out) instead of just replaying already-
// structured JSON straight into Postgres.
//
// See this node's Sticky Note if `data` isn't where your n8n version puts
// the parsed JSON from the "Extract From File" node.
const raw = $input.first().json;
const dataset = typeof raw.data === 'string' ? JSON.parse(raw.data) : (raw.data || raw);

const vendorsById = Object.fromEntries(
  (dataset.vendors || []).map((v) => [v.id, v])
);

const results = [];
for (const inv of dataset.invoices || []) {
  const vendor = vendorsById[inv.vendor_id] || {};
  const rawText = [
    'INVOICE',
    `Invoice Number: ${inv.invoice_number}`,
    `Vendor: ${vendor.name || 'UNKNOWN VENDOR'}`,
    `PO Number: ${inv.po_number || ''}`,
    `Amount: $${inv.amount}`,
    `Quantity: ${inv.quantity}`,
    `Unit Price: $${inv.unit_price}`,
  ].join('\n');

  results.push({
    json: {
      raw_text: rawText,
      _scenario: inv._scenario, // debugging only, not sent to /ingest
    },
  });
}

return results;
